            .map((e) => RepoSummary.fromJson(e as Map<String, dynamic>))
            .toList(),
        rights: (json['rights'] as List<dynamic>)
            .map((e) => RightRecord.fromJson(e as Map<String, dynamic>))
            .toList(),
        accounts: (json['accounts'] as List<dynamic>)
            .map((e) => LinkedAccount.fromJson(e as Map<String, dynamic>))
            .toList(),
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// Namespaces bound to this VTC that contain, or are contained by, `resource`.
  final List<GitNamespace> namespaces;

  /// Repositories within `resource`. `unmanaged` repositories are included only for
  /// callers holding `git.ns.admin` over them.
  final List<RepoSummary> repos;

  /// Rights within `resource` the caller may see: always the caller's own; every right
  /// on a resource the caller owns or administers. `reason` is omitted except on
  /// resources the caller owns or administers.
  final List<RightRecord> rights;

  /// The forge accounts linked to the caller's own DID — never another member's — at
  /// most one per forge. With `resource`, only the account on that resource's forge.
  /// Empty when the caller has linked none.
  final List<LinkedAccount> accounts;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'namespaces': namespaces.map((e) => e.toJson()).toList(),
        'repos': repos.map((e) => e.toJson()).toList(),
        'rights': rights.map((e) => e.toJson()).toList(),
        'accounts': accounts.map((e) => e.toJson()).toList(),
        if (ext != null) 'ext': ext!,
      };
}

/// A member reads the namespaces, repositories and rights they are entitled to see,
/// optionally narrowed to one resource, together with the forge accounts linked to
/// their own DID.
class Payload {
  const Payload({
    this.resource,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory Payload.fromJson(Map<String, dynamic> json) => Payload(
        resource: json['resource'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// Narrow the answer to this resource and everything inside it. Absent: everything the
  /// caller may see.
  final Resource? resource;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (resource != null) 'resource': resource!,
        if (ext != null) 'ext': ext!,
      };
}

