heck"],"properties":{"workflow":{"type":"boolean","description":"The verify-trust check runs on the repository\'s pull requests — from a workflow committed to it, or, where the forge supports it, required on it from the namespace\'s own bridge-managed workflow repository at a pinned commit."},"keyring":{"type":"boolean","description":"The exempt platform keyring for forge-signed merge commits is committed, or the forge\'s plan does not need one."},"variables":{"type":"boolean","description":"The repository names the Trust Registry and this VTC as its trust anchors."},"requiredCheck":{"type":"boolean","description":"The forge refuses to merge into the default branch unless the verify-trust check passes, with no bypass, and a pull request cannot change what that check runs: an organisation-required workflow, code-owner review of workflow files, or protected workflow paths, as the forge allows."}}},"RepoVisibility":{"title":"RepoVisibility","type":"string","enum":["public","private"],"description":"Repository visibility on the forge."},"GitNamespace":{"title":"GitNamespace","description":"The VTC\'s binding to one owner on one forge.","type":"object","additionalProperties":false,"required":["id","forge","owner","mode","state"],"properties":{"id":{"\$ref":"#/\$defs/NamespaceId"},"forge":{"\$ref":"#/\$defs/ForgeHost"},"owner":{"\$ref":"#/\$defs/Segment","description":"The organisation or user on the forge, lowercased."},"kind":{"type":"string","enum":["organization","user"],"description":"Whether the owner is an organisation or a personal account, as the forge reports it. Present once known: a bridge-mode namespace learns it when binding completes, and a manual-mode namespace MAY never learn it."},"mode":{"type":"string","enum":["bridge","manual"],"description":"`bridge` — a bridge service acts on the forge for this namespace (creates repositories, projects roles, reports drift). `manual` — no automation; people with forge access carry out the steps the VTC names, and th