orgeId":{"\$ref":"#/\$defs/ForgeId","description":"The forge\'s repository id. Absent until the forge has confirmed the repository exists (a `pendingCreate` repository, or one adopted in bridge mode before the first inspection)."},"visibility":{"\$ref":"#/\$defs/RepoVisibility"},"state":{"type":"string","enum":["pendingCreate","active","archived","detached","orphaned","unmanaged"],"description":"`pendingCreate` — the name is reserved and the repository is not yet confirmed on the forge. `active` — managed. `archived` — archived through git-ns/repo/archive; commit rights on it are revoked. `detached` — no longer governed: its namespace was unbound, or it moved outside the namespace. `orphaned` — its last owner left the community and ownership passed to the namespace admins, who have not yet named a new owner. `unmanaged` — it exists on the forge inside a bound namespace but was never created or adopted through the VTC."},"owners":{"type":"array","uniqueItems":true,"items":{"\$ref":"#/\$defs/Did"},"description":"The DIDs holding `git.repo.own` on this repository by an explicit grant. Empty only for an `unmanaged` repository, and for an `orphaned` one whose ownership rests with the namespace admins by implication."},"bootstrap":{"\$ref":"#/\$defs/Bootstrap"},"sync":{"\$ref":"#/\$defs/Sync"}}},"Sync":{"title":"Sync","description":"How the forge compares with the VTC\'s projection for one repository.","type":"object","additionalProperties":false,"required":["state","drift"],"properties":{"state":{"type":"string","enum":["inSync","drift","pending","unchecked"],"description":"`inSync` — the last comparison found no drift. `drift` — it found some, listed in `drift`. `pending` — a change has been sent to the forge and not yet confirmed. `unchecked` — nothing compares this repository (a manual-mode namespace)."},"checkedAt":{"type":"string","format":"date-time","description":"When the forge was last compared. Absent if never."},"drift":{"type":"array","items":{"\$ref":"#/\$defs/DriftItem"},"description":"Outstanding drift. Empty unless `state` is `drift`."}}},"DriftItem":{"title":"DriftItem","description":"One difference between the forge\'s observed state and the VTC\'s projection of a repository.","type":"object","additionalProperties":false,"required":["type","resource"],"properties":{"type":{"type":"string","enum":["roleAdded","roleRemoved","roleChanged","requiredCheckMissing","protectionWeakened","bootstrapMissing"],"description":"`roleAdded` — someone holds a forge role the projection does not give them. `roleRemoved` — a projected role is missing. `roleChanged` — a projected role is present at another level. `requiredCheckMissing` — the verify-trust check is no longer required. `protectionWeakened` — branch protection or a ruleset is weaker than the projection in another way (force-push allowed, bypass actors added). `bootstrapMissing` — a bootstrap file or variable is gone."},"resource":{"\$ref":"#/\$defs/RepoResource"},"account":{"\$ref":"#/\$defs/ForgeAccount","description":"Whose role differs, for the three role types."},"observed":{"type":"string","maxLength":256,"description":"What the forge shows, in the forge\'s own vocabulary (a role name such as `maintain`, a setting name). Absent when nothing is there."},"expected":{"type":"string","maxLength":256,"description":"What the projection calls for, in the forge\'s own vocabulary. Absent when the projection calls for nothing."}}},"ForgeAccount":{"title":"ForgeAccount","description":"A person\'s account on one forge. `id` is authoritative; `login` is for display only, because logins can be renamed and re-registered.","type":"object","additionalProperties":false,"required":["forge","id","login"],"properties":{"forge":{"\$ref":"#/\$defs/ForgeHost"},"id":{"\$ref":"#/\$defs/ForgeId"},"login":{"type":"string","minLength":1,"maxLength":100,"description":"The account\'s current login, as the forge reported it when last seen. Display only."}}},"ForgeId":{"title":"ForgeId","description":"An identifier the forge itself assigns — a repository id, a user or organisation id — carried as a string so a forge whose ids are not numbers needs no new version. GitHub and Forgejo ids are decimal integers written as strings (`\\"812736451\\"`). Unlike a name, it survives renames and transfers, which is why rights and bindings are keyed by it.","type":"string","minLength":1,"maxLength":64},"ForgeHost":{"title":"ForgeHost","description":"The lowercased DNS host of a forge: `github.com`, a GitHub Enterprise Server host, `codeberg.org`, or a self-hosted Forgejo instance such as `git.example.org`. No scheme, no port, no path. The host is a segment of every resource, so a right never crosses forges.","type":"string","minLength":3,"maxLength":253,"pattern":"^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\\\\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+\$"},"RepoResource":{"title":"RepoResource","description":"A forge-qualified resource naming exactly one repository: `<forge-host>/<owner>/<repo>`, lowercase.","type":"string","maxLength":455,"pattern":"^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\\\\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+/[a-z0-9_-][a-z0-9._-]{0,99}/[a-z0-9_-][a-z0-9._-]{0,99}\$"},"Bootstrap":{"title":"Bootstrap","description":"Whether each step that turns commit trust on for a repository is in place, as last reported. A step that this forge\'s plan does not need reads `true`.","type":"object","additionalProperties":false,"required":["workflow","keyring","variables","requiredCheck"],"properties":{"workflow":{"type":"boolean","description":"The verify-trust check runs on the repository\'s pull requests — from a workflow committed to it, or, where the forge supports it, required on it from the namespace\'s own bridge-managed workflow repository at a pinned commit."},"keyring":{"type":"boolean","description":"The exempt platform keyring for forge-signed merge commits is committed, or the forge\'s plan does not need one."},"variables":{"type":"boolean","description":"The repository names the Trust Registry and this VTC as its trust anchors."},"requiredCheck":{"type":"boolean","description":"The forge refuses to merge into the default branch unless the verify-trust check passes, with no bypass, and a pull request cannot change what that check runs: an organisation-required workflow, code-owner review of workflow files, or protected workflow paths, as the forge allows."}}},"RepoVisibility":{"title":"RepoVisibility","type":"string","enum":["public","private"],"description":"Repository visibility on the forge."},"GitNamespace":{"title":"GitNamespace","description":"The VTC\'s binding to one owner on one forge.","type":"object","additionalProperties":false,"required":["id","forge","owner","mode","state"],"properties":{"id":{"\$ref":"#/\$defs/NamespaceId"},"forge":{"\$ref":"#/\$defs/ForgeHost"},"owner":{"\$ref":"#/\$defs/Segment","description":"The organisation or user on the forge, lowercased."},"kind":{"type":"string","enum":["organization","user"],"description":"Whether the owner is an organisation or a personal account, as the forge reports it. Present once known: a bridge-mode namespace learns it when binding completes, and a manual-mode namespace MAY never learn it."},"mode":{"type":"string","enum":["bridge","manual"],"description":"`bridge` — a bridge service acts on the forge for this namespace (creates repositories, projects roles, reports drift). `manual` — no automation; people with forge access carry out the steps the VTC names, and the VTC governs the rights alone."},"state":{"type":"string","enum":["pending","bound"],"description":"`pending` — binding has started and the forge-side proof has not arrived yet. `bound` — the VTC governs rights under this namespace."}}},"Segment":{"title":"Segment","description":"One lowercased owner or repository name. Forges compare these case-insensitively, so the wire form is always lowercase and a producer lowercases before sending. A leading `.` is refused, which rules out `.` and `..`.","type":"string","minLength":1,"maxLength":100,"pattern":"^[a-z0-9_-][a-z0-9._-]*\$"},"NamespaceId":{"title":"NamespaceId","description":"The VTC\'s opaque identifier for a namespace, assigned when it is bound. Stable for the life of the binding; never reused for another binding.","type":"string","minLength":1,"maxLength":128}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: false,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: false,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: responsePayloadSchemaJson,
);
